function brand(footer = false) {
  return `<a href="/" class="brand ${footer ? 'brand-light' : ''}" aria-label="Nexora Logistic, inicio"><span class="brand-symbol"><img src="/assets/nexora-original.jpg" alt="" width="1536" height="1024"></span><span class="brand-wordmark"><img src="/assets/nexora-original.jpg" alt="Nexora Logistic" width="1536" height="1024"></span></a>`;
}
function header(path) {
  const nav = [['/', 'Inicio'], ['/nosotros/', 'Nosotros'], ['/servicios/', 'Servicios'], ['/cobertura/', 'Cobertura'], ['/blog/', 'Novedades'], ['/contacto/', 'Contacto']];
  return `<div class="utility-bar"><div class="container utility-inner"><span class="utility-note"><span class="status-dot"></span> Distribución inteligente. Confianza en movimiento.</span><span class="utility-country">${icon('map-pin')} Empresa paraguaya <span class="flag-py" aria-label="Paraguay"></span></span></div></div>
    <header class="site-header"><div class="container header-inner">${brand()}<nav class="desktop-nav" aria-label="Navegación principal">${nav.map(([href, label]) => `<a href="${href}" ${path === href || (href !== '/' && path.startsWith(href)) ? 'class="active" aria-current="page"' : ''}>${label}</a>`).join('')}</nav><div class="header-actions"><a class="client-link" href="/clientes/">${icon('user-round')} <span>Acceso clientes</span></a><a href="/contacto/" class="button button-red button-small">Cotizá tu envío ${arrow()}</a><button class="menu-toggle" aria-label="Abrir menú" aria-expanded="false" aria-controls="mobile-menu">${icon('menu')}</button></div></div><nav id="mobile-menu" class="mobile-nav" aria-label="Navegación móvil" hidden>${nav.map(([href, label]) => `<a href="${href}" ${path === href ? 'aria-current="page"' : ''}>${label} ${icon('arrow-right')}</a>`).join('')}<a href="/clientes/">Acceso clientes ${icon('user-round')}</a></nav></header>`;
}
function footer() {
  return `<footer class="site-footer"><div class="container footer-grid"><div class="footer-brand">${brand(true)}<p>Conectamos lo que importa.<br>Llevamos tu negocio más lejos.</p><span class="footer-country">${icon('map-pin')} Desde Paraguay, para todo el país.</span></div><div><h3>Explorá Nexora</h3><a href="/nosotros/">Nosotros</a><a href="/servicios/">Nuestros servicios</a><a href="/cobertura/">Cobertura nacional</a><a href="/blog/">Ideas en movimiento</a></div><div><h3>Conectemos</h3><a href="/contacto/">Solicitá una cotización</a><a href="/clientes/">Portal de clientes</a><a href="mailto:${contactEmail}">${contactEmail}</a><span>Asunción, Paraguay</span></div><div class="footer-last"><h3>Tu próximo destino<br>empieza con una charla.</h3><a href="/contacto/" class="footer-cta">Hablemos ${arrow()}</a><span class="footer-availability"><span class="status-dot"></span> Un equipo de tu lado</span></div></div><div class="container footer-bottom"><span>© ${new Date().getFullYear()} Nexora Logistic. Todos los derechos reservados.</span><a href="/privacidad/">Privacidad</a><span>HECHO PARA LLEGAR MÁS LEJOS ${icon('arrow-up-right')}</span></div></footer><a class="floating-contact" href="/contacto/" aria-label="Contactar con Nexora">${icon('message-circle')}<span>Hablemos</span></a>`;
}
function eyebrow(text, light = false) { return `<div class="eyebrow ${light ? 'eyebrow-light' : ''}"><span></span>${text}</div>`; }
function cta() {
  return `<section class="cta-section"><div class="container cta-inner"><div>${eyebrow('EL SIGUIENTE PASO ES TUYO', true)}<h2>Tu negocio no se detiene.<br>Nosotros lo acompañamos.</h2></div><a href="/contacto/" class="button button-white">Hablemos de tu operación ${arrow()}</a></div></section>`;
}
function breadcrumbs(title, parent) { return `<div class="breadcrumbs"><a href="/">Inicio</a>${icon('chevron-right')}${parent ? `<a href="${parent[0]}">${parent[1]}</a>${icon('chevron-right')}` : ''}<span>${title}</span></div>`; }
function pageHeading(label, title, desc, image) { return `<section class="page-heading ${image ? 'page-heading-photo' : ''}" ${image ? `style="--page-image: url('/assets/${image}')"` : ''}><div class="container">${breadcrumbs(label)}${eyebrow(label, !!image)}<h1>${title}</h1><p>${desc}</p></div></section>`; }
function serviceCard(service, index) {
  return `<a class="service-card" href="/servicios/${service.slug}/"><div class="service-photo ${service.photoClass}"><img src="/assets/${service.photo}" alt="${service.title}" loading="lazy" width="600" height="450"><span class="photo-icon">${icon(service.icon)}</span></div><div class="service-card-body"><span class="card-index">0${index + 1} <span>/ SOLUCIONES</span></span><h3>${service.title}</h3><p>${service.desc}</p><span class="card-link">Conocé más <span>${arrow()}</span></span></div></a>`;
}
function articleCard(article) { return `<a href="/blog/${article.slug}/" class="article-card"><div class="article-photo ${article.class}"><img src="/assets/${article.photo}" alt="" loading="lazy" width="800" height="500"></div><div class="article-meta"><span>${article.tag}</span><span>${article.time}</span></div><h3>${article.title}</h3><span class="text-link">Leer artículo ${arrow()}</span></a>`; }
function faq(items) { return `<div class="faq-list">${items.map(([q, a]) => `<details><summary>${q}<span>${icon('plus')}</span></summary><p>${a}</p></details>`).join('')}</div>`; }
function home() {
  return `<section class="hero"><img class="hero-image" src="/assets/nexora-hero.jpg" alt="Camión de Nexora Logistic en una ruta de Paraguay" fetchpriority="high" width="1942" height="809"><div class="hero-shade"></div><div class="container hero-content"><div class="hero-copy">${eyebrow('LOGÍSTICA QUE TE LLEVA MÁS LEJOS', true)}<h1>Movemos tu carga.<br>Impulsamos<br><span>tu negocio.</span></h1><p>Conectamos destinos, personas y oportunidades.<br>Soluciones logísticas a la medida de tu empresa,<br class="desktop-only"> en todo Paraguay.</p><div class="hero-buttons"><a href="/contacto/" class="button button-red">Cotizá tu envío ${arrow()}</a><a href="/servicios/" class="button button-outline">Explorá nuestras soluciones ${icon('arrow-right')}</a></div><div class="hero-bottom"><span class="hero-line"></span> TU CONFIANZA ES NUESTRO PUNTO DE PARTIDA.</div></div><div class="hero-label"><span class="hero-label-icon">${icon('shield-check')}</span><div><span>TRANQUILIDAD EN EL CAMINO</span><strong>Cada entrega importa.</strong></div>${arrow()}</div></div><div class="hero-caption">ASUNCIÓN, PARAGUAY <span>25°16′ S · 57°34′ O</span></div></section>
  <section class="trust-strip" aria-label="Nuestros compromisos"><div class="container trust-grid">${[['map-pinned', 'Todo Paraguay, conectado', 'Cobertura que acompaña tu crecimiento.'], ['scan-line', 'Visibilidad en cada etapa', 'Información clara de principio a fin.'], ['shield-check', 'Tu carga en buenas manos', 'Cuidado y compromiso en cada entrega.']].map(([i, title, text]) => `<div class="trust-item">${icon(i)}<div><h2>${title}</h2><p>${text}</p></div></div>`).join('')}</div></section>
  <section class="section services-section"><div class="container"><div class="section-heading"><div>${eyebrow('NUESTRAS SOLUCIONES')}<h2>Tu logística, resuelta.<br>Tu negocio, en movimiento.</h2></div><div class="section-heading-aside"><p>Una necesidad, una solución.<br>Descubrí cómo podemos acompañarte.</p><a href="/servicios/" class="text-link">Ver todos los servicios ${arrow()}</a></div></div><div class="services-grid">${services.map(serviceCard).join('')}</div></div></section>
  <section class="section about-section"><div class="container about-grid"><div class="about-image"><img src="/assets/warehouse.jpg" alt="Almacén organizado para coordinar pedidos y distribución" loading="lazy" width="1200" height="800"><div class="about-image-note">${icon('package-check')}<span>Detrás de cada entrega,<br><strong>hay un equipo comprometido.</strong></span></div></div><div class="about-copy">${eyebrow('SOMOS NEXORA')}<h2>Más que logística.<br>Un equipo de tu lado.</h2><p>Sabemos que detrás de cada envío hay una promesa. Un cliente que espera, un proyecto que avanza y un negocio que confía.</p><p>Por eso, conectamos experiencia, planificación y atención cercana para que tu operación llegue a donde tiene que llegar.</p><div class="value-pair"><span>${icon('handshake')} Compromiso real</span><span>${icon('crosshair')} Atención al detalle</span></div><a href="/nosotros/" class="button button-navy">Conocé nuestra forma de trabajar ${arrow()}</a></div></div></section>
  <section class="coverage-teaser"><div class="container coverage-teaser-grid"><div>${eyebrow('CERCA, ESTÉS DONDE ESTÉS', true)}<h2>Un país entero.<br>Muchas oportunidades.<br><span>Una misma conexión.</span></h2><p>Desde Asunción, conectamos tu operación con destinos de todo Paraguay. Contanos dónde necesitás llegar.</p><a href="/cobertura/" class="button button-white">Explorá nuestra cobertura ${arrow()}</a></div><div class="coverage-visual"><div class="coverage-orbit"></div><img src="/assets/paraguay-map.svg" alt="Mapa de Paraguay" width="420" height="480"><span class="map-label label-asuncion"><span></span> Asunción</span><span class="map-label label-cde"><span></span> Ciudad del Este</span><span class="map-label label-encarnacion"><span></span> Encarnación</span><span class="map-label label-concepcion"><span></span> Concepción</span><div class="coverage-stamp">${icon('navigation')}<span>COBERTURA<br><strong>NACIONAL</strong></span></div></div></div></section>
  <section class="section process-section"><div class="container"><div class="section-heading"><div>${eyebrow('SIMPLE DE PRINCIPIO A FIN')}<h2>Vos marcás el destino.<br>Nosotros conectamos el camino.</h2></div><p class="heading-description">Una conversación es el comienzo<br>de una operación bien coordinada.</p></div><div class="steps-grid">${[['01', 'Te escuchamos', 'Conocemos tu carga, tus destinos y lo que tu negocio necesita.', 'messages-square'], ['02', 'Lo planificamos', 'Definimos una solución y coordinamos cada detalle con tu equipo.', 'clipboard-list'], ['03', 'Lo ponemos en marcha', 'Acompañamos la operación y te mantenemos al tanto.', 'truck'], ['04', 'Llegamos juntos', 'Cuidamos la entrega y seguimos cerca para el próximo paso.', 'package-check']].map(([n, title, text, i]) => `<div class="step"><span class="step-number">${n}</span>${icon(i)}<h3>${title}</h3><p>${text}</p></div>`).join('')}</div></div></section>
  ${cta()}`;
}
function about() { return `${pageHeading('NOSOTROS', 'Conectamos lo que importa.', 'Distribución inteligente. Confianza en movimiento.', 'nexora-hero.jpg')}<section class="section"><div class="container about-grid"><div>${eyebrow('NUESTRA FORMA DE VER LA LOGÍSTICA')}<h2>Tu negocio tiene un rumbo.<br>Nos mueve acompañarte.</h2><p class="large-copy">Somos Nexora Logistic, una empresa paraguaya que conecta mercados y personas a través de soluciones de logística y distribución.</p><p>Entendemos la logística como una relación de confianza. Escuchamos las necesidades de cada operación, planificamos con atención y trabajamos cerca de las personas que hacen que cada entrega sea posible.</p><p>Nuestro propósito es simple: que puedas concentrarte en tu negocio con un equipo que acompaña el movimiento de tu carga.</p></div><div class="editorial-photo"><img src="/assets/warehouse.jpg" alt="Infraestructura de almacenamiento logístico" loading="lazy" width="1200" height="800"><span>NEXORA LOGISTIC · PARAGUAY</span></div></div></section><section class="section soft-section"><div class="container mission-grid"><div>${eyebrow('NUESTRA MISIÓN')}<h2>Hacer que cada<br>conexión cuente.</h2><p>Brindar soluciones logísticas que conecten empresas, personas y destinos con eficiencia, seguridad y una atención cercana.</p></div><div>${eyebrow('NUESTRA VISIÓN')}<h2>Crecer junto a quienes<br>confían en nosotros.</h2><p>Construir relaciones duraderas y ser un aliado logístico para empresas que buscan llevar sus operaciones más lejos.</p></div></div></section><section class="section"><div class="container"><div class="section-heading"><div>${eyebrow('LO QUE NOS DEFINE')}<h2>Cuatro valores.<br>Un mismo compromiso.</h2></div></div><div class="values-grid">${[['shield-check','Confianza','Cumplimos lo que acordamos y comunicamos con claridad.'],['crosshair','Precisión','Los detalles importan, desde el primer contacto hasta la entrega.'],['handshake','Compromiso','Tu operación también es nuestra responsabilidad.'],['chart-no-axes-combined','Eficiencia','Buscamos una forma más simple y ordenada de conectar cada etapa.']].map(([i,t,d],n)=>`<div class="value-card"><span>0${n+1}</span>${icon(i)}<h3>${t}</h3><p>${d}</p></div>`).join('')}</div></div></section>${cta()}`; }
function servicesPage() { return `${pageHeading('NUESTROS SERVICIOS', 'El movimiento de tu negocio,<br>en buenas manos.', 'Soluciones que se conectan entre sí y se adaptan a lo que tu operación necesita.')}<section class="section"><div class="container"><div class="services-grid">${services.map(serviceCard).join('')}</div><div class="custom-solution">${icon('puzzle')}<div><h3>¿Tu operación necesita algo diferente?</h3><p>Conversemos sobre tus destinos, volúmenes y condiciones especiales.</p></div><a href="/contacto/?servicio=Solución%20a%20medida" class="button button-navy">Diseñemos una solución ${arrow()}</a></div></div></section><section class="section soft-section"><div class="container faq-layout"><div>${eyebrow('ANTES DE EMPEZAR')}<h2>Buenas preguntas.<br>Respuestas claras.</h2><p>Si tu consulta es más específica,<br>nuestro equipo te acompaña.</p><a href="/contacto/" class="text-link">Hablemos ${arrow()}</a></div>${faq([['¿Cómo solicito una cotización?', 'Completá el formulario con el tipo de servicio, los destinos y una descripción de tu carga. Podrás preparar tu solicitud y enviarla por correo al equipo de Nexora.'], ['¿Puedo combinar varios servicios?', 'Sí. Podemos conversar sobre una solución que conecte transporte, almacenamiento, preparación de pedidos y distribución según las necesidades de tu operación.'], ['¿Qué datos necesito para coordinar un envío?', 'Indicá el origen, el destino, la cantidad de bultos, el peso o volumen aproximado y cualquier condición especial de manejo. Cuanta más información compartas, mejor podremos planificar.'], ['¿Los tiempos de entrega son iguales para todos los destinos?', 'Los tiempos se coordinan según la ruta, el tipo de carga y las condiciones de la operación. Consultá por tu destino para acordar una planificación concreta.']])}</div></section>${cta()}`; }
function serviceDetail(service) { return `<section class="service-detail-heading"><div class="container">${breadcrumbs(service.title, ['/servicios/', 'Servicios'])}<div class="service-detail-grid"><div>${eyebrow(service.label)}<h1>${service.title}</h1><p>${service.intro}</p><a href="/contacto/?servicio=${encodeURIComponent(service.title)}" class="button button-red">Cotizá este servicio ${arrow()}</a></div><div class="detail-photo ${service.photoClass}"><img src="/assets/${service.photo}" alt="${service.title}" width="900" height="600"></div></div></div></section><section class="section"><div class="container detail-content"><div>${eyebrow('PENSADO PARA TU OPERACIÓN')}<h2>${service.short}</h2><p class="large-copy">${service.body}</p><a href="/contacto/" class="text-link">Contanos qué necesitás ${arrow()}</a></div><div class="included-box"><h3>¿Cómo te acompañamos?</h3>${service.details.map(d=>`<div>${icon('check')}<span>${d}</span></div>`).join('')}<p>El alcance y las condiciones de cada servicio se definen al coordinar tu operación.</p></div></div></section><section class="section soft-section"><div class="container"><div class="section-heading"><div>${eyebrow('TODO SE CONECTA')}<h2>Otras formas de acompañarte.</h2></div><a href="/servicios/" class="text-link">Todos los servicios ${arrow()}</a></div><div class="related-services">${services.filter(s=>s.slug!==service.slug).map((s,i)=>`<a href="/servicios/${s.slug}/">${icon(s.icon)}<div><h3>${s.title}</h3><p>${s.short}</p></div>${arrow()}</a>`).join('')}</div></div></section>${cta()}`; }
function coveragePage() { return `${pageHeading('COBERTURA NACIONAL', 'Cerca de tu negocio.<br>Cerca de tu próximo destino.', 'Coordinamos conexiones desde Asunción hacia destinos de todo Paraguay.')}<section class="section coverage-section"><div class="container coverage-page-grid"><div class="coverage-controls">${eyebrow('ENCONTRÁ TU CONEXIÓN')}<h2>¿A dónde querés llegar?</h2><p>Explorá algunos destinos de referencia o consultanos por una localidad.</p><label class="search-field">${icon('search')}<input id="city-search" type="search" placeholder="Buscá una ciudad o región" aria-label="Buscar ciudad o región"></label><div class="region-filters" role="group" aria-label="Filtrar región">${[['all','Todo el país'],['central','Centro'],['este','Este'],['sur','Sur'],['norte','Norte'],['chaco','Chaco']].map(([value,text])=>`<button type="button" data-region="${value}" class="filter-chip ${value==='all'?'selected':''}" aria-pressed="${value==='all'}">${text}</button>`).join('')}</div><div id="city-list" class="city-list"></div><p class="coverage-disclaimer">Los destinos son orientativos. Disponibilidad, frecuencia y plazos se confirman al coordinar cada servicio.</p></div><div class="interactive-map"><div class="map-top-label">PARAGUAY <span>COBERTURA NACIONAL</span></div><div class="map-canvas"><img src="/assets/paraguay-map.svg" alt="Contorno geográfico de Paraguay" width="420" height="480">${cities.map((city,i)=>`<button class="map-pin ${i===0?'selected':''}" data-city="${i}" style="left:${city.x}%;top:${city.y}%" aria-label="Ver ${city.name}"><span></span><b>${city.name.split(' y ')[0]}</b></button>`).join('')}</div><div id="map-destination" class="map-destination"></div></div></div></section><section class="section soft-section"><div class="container destination-cta">${icon('map-pinned')}<div><h2>Tu destino también importa.</h2><p>Si no encontrás tu localidad, contanos dónde necesitás llegar. Buscamos juntos la conexión.</p></div><a href="/contacto/" class="button button-red">Consultá tu destino ${arrow()}</a></div></section>${cta()}`; }
function blogPage() { return `${pageHeading('IDEAS EN MOVIMIENTO', 'Información útil.<br>Nuevas perspectivas.', 'Guías y recursos para entender tu logística y tomar mejores decisiones.')}<section class="section"><div class="container"><div class="blog-filters" role="group" aria-label="Filtrar artículos">${[['all','Todos los artículos'],['GUÍA PRÁCTICA','Guías prácticas'],['NEGOCIOS','Negocios'],['CONFIANZA','Confianza']].map(([tag,t])=>`<button data-blog-filter="${tag}" class="filter-chip ${tag==='all'?'selected':''}" aria-pressed="${tag==='all'}">${t}</button>`).join('')}</div><div id="blog-grid" class="articles-grid">${articles.map(articleCard).join('')}</div><div class="resource-note">${icon('book-open')}<p>Ideas para tu próxima operación.<br><strong>El conocimiento también conecta.</strong></p></div></div></section>${cta()}`; }
function articlePage(article) { return `<section class="article-header"><div class="container">${breadcrumbs(article.title, ['/blog/', 'Novedades'])}<div class="article-meta"><span>${article.tag}</span><span>${article.time}</span></div><h1>${article.title}</h1><p>${article.intro}</p><span class="article-author">Por el equipo de Nexora Logistic</span><div class="article-cover ${article.class}"><img src="/assets/${article.photo}" alt="" width="1200" height="600"></div></div></section><section class="section"><div class="container article-layout"><aside><span>EN ESTE ARTÍCULO</span>${article.sections.map(([t],i)=>`<a href="#seccion-${i}">${t}</a>`).join('')}<button class="text-link" id="share-article">Compartir artículo ${icon('share-2')}</button></aside><div class="article-body">${article.sections.map(([t,p],i)=>`<section id="seccion-${i}"><h2>${t}</h2><p>${p}</p></section>`).join('')}<div class="article-contact"><h3>¿Lo ponemos en práctica?</h3><p>Contanos sobre tu próxima operación. Nuestro equipo te ayuda a planificarla.</p><a href="/contacto/" class="text-link">Conectá con Nexora ${arrow()}</a></div><a href="/blog/" class="text-link">${icon('arrow-left')} Volver a los artículos</a></div></div></section>${cta()}`; }
function contactPage() { return `${pageHeading('HABLEMOS', 'El próximo movimiento<br>empieza acá.', 'Contanos qué necesitás. Juntos encontramos la mejor forma de llegar.')}<section class="section contact-section"><div class="container contact-grid"><div class="contact-info">${eyebrow('UN EQUIPO DE TU LADO')}<h2>Tu operación merece<br>una buena conversación.</h2><p>Completá los datos para preparar tu solicitud. Al terminar, podrás revisarla y enviarla por correo a nuestro equipo.</p><div class="contact-channel">${icon('mail')}<div><span>ESCRIBINOS</span><a href="mailto:${contactEmail}">${contactEmail}</a></div></div><div class="contact-channel">${icon('map-pin')}<div><span>ESTAMOS EN PARAGUAY</span><strong>Asunción · Cobertura nacional</strong></div></div><div class="contact-promise">${icon('handshake')}<p>Escuchamos primero.<br><strong>Planificamos con vos.</strong></p></div><p class="small-note">Los datos de contacto provienen del material de marca y deben confirmarse antes del lanzamiento comercial.</p></div><div class="quote-card"><div class="form-heading"><span>01 / CONECTEMOS</span><h2>Contanos sobre tu envío</h2><p>Los campos con * son obligatorios.</p></div><form id="quote-form"><div class="form-row"><label>Nombre y apellido *<input name="nombre" autocomplete="name" required maxlength="100" placeholder="Tu nombre"></label><label>Empresa<input name="empresa" autocomplete="organization" maxlength="120" placeholder="Nombre de tu empresa"></label></div><div class="form-row"><label>Correo electrónico *<input name="email" type="email" autocomplete="email" required maxlength="160" placeholder="nombre@empresa.com"></label><label>Teléfono<input name="telefono" type="tel" autocomplete="tel" maxlength="35" placeholder="+595"></label></div><label>¿Qué solución necesitás? *<select name="servicio" required><option value="">Seleccioná un servicio</option>${services.map(s=>`<option>${s.title}</option>`).join('')}<option>Solución a medida</option></select></label><div class="form-row"><label>Origen *<input name="origen" required maxlength="120" placeholder="Ciudad de retiro"></label><label>Destino *<input name="destino" required maxlength="120" placeholder="Ciudad de entrega"></label></div><label>Un poco más sobre tu operación *<textarea name="mensaje" rows="4" required minlength="10" maxlength="3000" placeholder="Tipo de carga, cantidad de bultos, peso aproximado, frecuencia o cualquier detalle que nos ayude a planificar."></textarea></label><label class="checkbox-label"><input type="checkbox" name="privacidad" required><span>Leí la <a href="/privacidad/">política de privacidad</a> y acepto compartir estos datos para preparar mi consulta. *</span></label><button type="submit" class="button button-red button-full">Preparar mi solicitud ${arrow()}</button><p class="form-footnote">${icon('lock-keyhole')} Tus datos se usan únicamente para preparar esta solicitud.</p></form><div id="quote-result" hidden aria-live="polite"></div></div></div></section>`; }
function clientPage() { return `<section class="portal-auth-section"><div class="container">${breadcrumbs("Clientes")}<p><a class="text-link" href="#customer-panel">Ver el panel de demostración ${arrow()}</a></p><div class="auth-layout"><div class="auth-intro">${eyebrow("TU CONFIANZA NOS MUEVE", true)}<h1>Más cerca de<br>tu operación.</h1><p>Una conexión directa con el equipo que acompaña a tu negocio.</p><div class="auth-benefits"><div>${icon("fingerprint")}<span><strong>Tu identidad, protegida.</strong>Ingresá con tu cuenta de Google.</span></div><div>${icon("building-2")}<span><strong>Un acceso para tu empresa.</strong>Habilitado por el equipo de Nexora.</span></div></div><div class="auth-intro-photo"><img src="/assets/nexora-hero.jpg" alt="Camión de Nexora en ruta" width="1942" height="809"><span>${icon("route")} CONECTAMOS LO QUE IMPORTA.</span></div></div><div id="customer-auth-root" class="auth-card"><span class="auth-eyebrow">PORTAL DE CLIENTES</span><h2>Conectando tu cuenta.</h2><p role="status">Estamos comprobando el acceso.</p><noscript>Activá JavaScript para iniciar sesión con Google.</noscript></div></div></div></section>${clientPanelPreview()}`; }
function clientPanelPreview() { return `<section id="customer-panel" class="section portal-section"><div class="container"><div class="demo-banner">${icon('info')}<span><strong>Vista de demostración.</strong> Los envíos son ejemplos ficticios. Para gestionar operaciones reales, contactá con el equipo de Nexora.</span><a href="/contacto/">Contactar ${arrow()}</a></div><div class="portal-shell"><div class="portal-sidebar">${brand()}<div class="portal-company">${icon('building-2')}<div>Empresa de ejemplo<span>Cuenta de demostración</span></div></div><button class="portal-tab selected" data-portal-tab="envios">${icon('package')} Mis envíos</button><button class="portal-tab" data-portal-tab="documentos">${icon('files')} Documentos</button><button class="portal-tab" data-portal-tab="reportes">${icon('chart-no-axes-combined')} Resumen</button><a class="portal-help" href="/contacto/">${icon('headset')} Hablá con tu equipo</a></div><div class="portal-main" id="portal-content"></div></div></div></section>`; }
function privacyPage() { return `${pageHeading("PRIVACIDAD", "Tu confianza también<br>se cuida acá.", "Cómo se usan tus datos en la web y el portal de clientes.")}<section class="section"><div class="container legal-copy"><h2>Datos del formulario</h2><p>Los datos que ingresás en la cotización se usan dentro de tu navegador para preparar un resumen. El formulario no envía ni almacena esos datos en un servidor.</p><h2>Envío por correo</h2><p>La opción «Enviar por email» abre tu aplicación de correo con el contenido preparado. Vos revisás y confirmás el envío desde esa aplicación. El manejo posterior del correo depende de tu proveedor y de los procesos de atención de Nexora.</p><h2>Acceso con Google</h2><p>Si elegís iniciar sesión, Google y Supabase procesan la identificación. Nexora recibe los datos básicos de tu perfil, como tu nombre y correo, para reconocer tu cuenta. No solicitamos acceso a tu Gmail, Drive ni contactos. La identificación no habilita por sí sola el acceso a una empresa: Nexora asigna esa autorización.</p><h2>Sesión y permisos</h2><p>El portal guarda la sesión de acceso en el almacenamiento local de tu navegador para mantenerte identificado y renovar la sesión. Podés cerrarla mediante «Cerrar sesión». Supabase almacena tu cuenta y la vinculación autorizada con tu empresa. Si compartís un dispositivo, cerrá la sesión al terminar.</p><h2>Recursos y seguimiento</h2><p>Esta web no incorpora herramientas de analítica ni cookies de publicidad. Las imágenes, fuentes, iconos y la biblioteca de acceso se sirven desde el sitio. Al iniciar sesión se establece una conexión con Supabase y Google, sujetos a sus respectivas políticas de privacidad.</p><h2>Contacto</h2><p>Para consultar sobre tus datos, solicitar la baja de tu cuenta o revisar una habilitación, escribí a <a href="mailto:${contactEmail}">${contactEmail}</a>.</p><a class="text-link" href="/contacto/">Volver a contacto ${arrow()}</a></div></section>`; }
function notFound() { return `<section class="section not-found"><div class="container">${eyebrow('404 · RECALCULANDO EL CAMINO')}<h1>Este destino<br>no está en la ruta.</h1><p>La página que buscás no está disponible. Volvamos al punto de partida.</p><a href="/" class="button button-red">Volver al inicio ${icon('arrow-right')}</a></div></section>`; }

const routeTitles = { '/': 'Nexora Logistic | Confianza en movimiento', '/nosotros/': 'Nosotros | Nexora Logistic', '/servicios/': 'Soluciones logísticas | Nexora Logistic', '/cobertura/': 'Cobertura nacional | Nexora Logistic', '/blog/': 'Ideas en movimiento | Nexora Logistic', '/contacto/': 'Contacto y cotización | Nexora Logistic', '/clientes/': 'Portal de clientes | Nexora Logistic', '/privacidad/': 'Privacidad | Nexora Logistic' };
function render(keepScroll = false) {
  const path = location.pathname.slice(siteBase.length).replace(/\/+$/, '') + '/';
  let content;
  if (path === '/') content = home();
  else if (path === '/nosotros/') content = about();
  else if (path === '/servicios/') content = servicesPage();
  else if (path === '/cobertura/') content = coveragePage();
  else if (path === '/blog/') content = blogPage();
  else if (path === '/contacto/') content = contactPage();
  else if (path === '/clientes/') content = clientPage();
  else if (path === '/privacidad/') content = privacyPage();
  else if (services.some(s => path === `/servicios/${s.slug}/`)) { const s = services.find(s => path === `/servicios/${s.slug}/`); content = serviceDetail(s); routeTitles[path] = `${s.title} | Nexora Logistic`; }
  else if (articles.some(a => path === `/blog/${a.slug}/`)) { const a = articles.find(a => path === `/blog/${a.slug}/`); content = articlePage(a); routeTitles[path] = `${a.title} | Nexora Logistic`; }
  else content = notFound();
  $('#app').innerHTML = `${header(path)}<main id="main" tabindex="-1">${content}</main>${footer()}`;
  document.title = routeTitles[path] || 'Página no encontrada | Nexora Logistic';
  refreshIcons();
  bindShared();
  if (path === '/contacto/') bindQuote();
  if (path === '/cobertura/') bindCoverage();
  if (path === '/blog/') bindBlog();
  if (path === '/clientes/') {
    $$('[data-portal-tab]').forEach(button => button.addEventListener('click', () => renderPortal(button.dataset.portalTab)));
    renderPortal('envios');
    const root = $('#customer-auth-root');
    import(siteBase + '/portal-auth.js').then(({mountPortal}) => {
      if (root.isConnected) return mountPortal(root);
    }).catch(() => {
      if (root.isConnected) root.innerHTML = '<h2>No pudimos cargar el acceso.</h2><p>Recargá la página para volver a intentarlo.</p>';
    });
  }
  if ($('#share-article')) $('#share-article').addEventListener('click', shareArticle);
  if (!keepScroll) window.scrollTo({ top: 0, behavior: 'instant' });
}
function refreshIcons() {
  if (siteBase) {
    $$('[href^="/"], [src^="/"]').forEach(element => {
      const attr = element.hasAttribute('href') ? 'href' : 'src';
      const value = element.getAttribute(attr);
      if (!value.startsWith('//') && value !== siteBase && !value.startsWith(siteBase + '/')) element.setAttribute(attr, siteBase + value);
    });
    $$('[style]').forEach(element => {
      const style = element.getAttribute('style');
      element.setAttribute('style', style.replace(/url\((['"]?)\/assets\//g, `url($1${siteBase}/assets/`));
    });
  }
  if (window.lucide) window.lucide.createIcons({ attrs: { 'stroke-width': 1.6 } });
}
function bindShared() {
  $('.menu-toggle').addEventListener('click', () => {
    const open = $('.menu-toggle').getAttribute('aria-expanded') === 'true';
    $('.menu-toggle').setAttribute('aria-expanded', String(!open));
    $('.menu-toggle').setAttribute('aria-label', open ? 'Abrir menú' : 'Cerrar menú');
    $('#mobile-menu').hidden = open;
  });
}
document.addEventListener('click', event => {
  const link = event.target.closest('a');
  if (!link || event.button !== 0 || event.metaKey || event.ctrlKey || event.shiftKey || event.altKey || link.target === '_blank' || link.hasAttribute('download')) return;
  const url = new URL(link.href, location.origin);
  if (url.origin !== location.origin || !['http:', 'https:'].includes(url.protocol) || url.hash) return;
  if (siteBase && !url.pathname.startsWith(siteBase + '/')) return;
  event.preventDefault();
  history.pushState({}, '', url.pathname + url.search);
  render();
  $('#main').focus({ preventScroll: true });
});
window.addEventListener('popstate', () => render());
document.addEventListener('keydown', event => { if (event.key === 'Escape' && $('#mobile-menu') && !$('#mobile-menu').hidden) { $('#mobile-menu').hidden = true; $('.menu-toggle').setAttribute('aria-expanded', 'false'); $('.menu-toggle').focus(); } });
function toast(text) { $('#toast').textContent = text; $('#toast').classList.add('visible'); clearTimeout(window.toastTimer); window.toastTimer = setTimeout(() => $('#toast').classList.remove('visible'), 3500); }
function downloadFile(name, text, type = 'text/plain;charset=utf-8') { const url = URL.createObjectURL(new Blob([text], { type })); const a = document.createElement('a'); a.href = url; a.download = name; a.click(); setTimeout(() => URL.revokeObjectURL(url), 1500); }

function bindQuote() {
  const form = $('#quote-form');
  const initialService = new URLSearchParams(location.search).get('servicio');
  if (initialService && [...form.elements.servicio.options].some(o => o.value === initialService)) form.elements.servicio.value = initialService;
  form.addEventListener('submit', event => {
    event.preventDefault();
    if (!form.reportValidity()) return;
    const data = Object.fromEntries(new FormData(form));
    const body = `SOLICITUD DE COTIZACIÓN · NEXORA LOGISTIC\n\nNombre: ${data.nombre}\nEmpresa: ${data.empresa || 'No indicada'}\nCorreo: ${data.email}\nTeléfono: ${data.telefono || 'No indicado'}\nServicio: ${data.servicio}\nOrigen: ${data.origen}\nDestino: ${data.destino}\n\nDetalles:\n${data.mensaje}`;
    form.hidden = true;
    $('.form-heading').hidden = true;
    const result = $('#quote-result');
    result.hidden = false;
    result.innerHTML = `<div class="success-icon">${icon('check')}</div><span class="eyebrow">TU PRÓXIMO PASO</span><h2>Tu solicitud está lista.</h2><p>Revisá el resumen y abrí tu correo para enviarlo al equipo. La solicitud todavía no fue enviada.</p><div class="quote-summary"><span>${escapeHTML(data.servicio)}</span><h3>${escapeHTML(data.origen)} ${icon('arrow-right')} ${escapeHTML(data.destino)}</h3><p>${escapeHTML(data.nombre)}${data.empresa ? ` · ${escapeHTML(data.empresa)}` : ''}</p><p>${escapeHTML(data.email)}</p><p class="summary-message">${escapeHTML(data.mensaje)}</p></div><a id="send-email" class="button button-red button-full">Enviar por email ${icon('mail')}</a><button id="download-quote" class="button button-ghost button-full">Descargar solicitud ${icon('download')}</button><button id="edit-quote" class="text-link">${icon('arrow-left')} Editar mis datos</button><p class="small-note">Si no tenés un programa de correo configurado, descargá el resumen y envialo a ${contactEmail}.</p>`;
    $('#send-email').href = `mailto:${contactEmail}?subject=${encodeURIComponent(`Cotización · ${data.servicio} · ${data.empresa || data.nombre}`)}&body=${encodeURIComponent(body)}`;
    $('#download-quote').addEventListener('click', () => downloadFile('solicitud-nexora.txt', body));
    $('#edit-quote').addEventListener('click', () => { result.hidden = true; form.hidden = false; $('.form-heading').hidden = false; form.elements.nombre.focus(); });
    refreshIcons();
    result.scrollIntoView({ block: 'center', behavior: 'smooth' });
  });
}
function bindCoverage() {
  let region = 'all', query = '', selected = 0;
  function updateList() {
    const normalize = v => v.normalize('NFD').replace(/[\u0300-\u036f]/g, '').toLowerCase();
    const filtered = cities.map((city, i) => ({ ...city, i })).filter(c => (region === 'all' || c.region === region) && normalize(`${c.name} ${c.label}`).includes(normalize(query)));
    $('#city-list').innerHTML = filtered.length ? filtered.map(city => `<button class="city-row ${city.i === selected ? 'selected' : ''}" data-city="${city.i}">${icon('map-pin')}<span><strong>${city.name}</strong><small>${city.label}</small></span>${icon('arrow-up-right')}</button>`).join('') : `<div class="empty-state">${icon('search-x')}<p>No encontramos esa localidad en esta lista.</p><a href="/contacto/" class="text-link">Consultá tu destino ${arrow()}</a></div>`;
    $$('.map-pin').forEach(pin => { const i = Number(pin.dataset.city); pin.classList.toggle('muted', !filtered.some(city => city.i === i)); });
    $$('#city-list [data-city]').forEach(button => button.addEventListener('click', () => selectCity(Number(button.dataset.city))));
    refreshIcons();
  }
  function selectCity(index) { selected = index; const city = cities[index]; $('#map-destination').innerHTML = `<span class="destination-pin">${icon('map-pin')}</span><div><span>${city.label}</span><h3>${city.name}</h3><p>${city.detail}</p></div><a href="/contacto/" aria-label="Consultar por ${city.name}">${arrow()}</a>`; $$('.map-pin').forEach(pin=>{ const active=Number(pin.dataset.city)===index; pin.classList.toggle('selected',active); pin.setAttribute('aria-pressed',String(active)); }); updateList(); }
  $('#city-search').addEventListener('input', event => { query = event.target.value; updateList(); });
  $$('[data-region]').forEach(button => button.addEventListener('click', () => { region = button.dataset.region; $$('[data-region]').forEach(b=>{ b.classList.toggle('selected',b===button); b.setAttribute('aria-pressed',String(b===button)); }); updateList(); }));
  $$('.map-pin').forEach(button => button.addEventListener('click', () => selectCity(Number(button.dataset.city))));
  selectCity(0);
}
function bindBlog() { $$('[data-blog-filter]').forEach(button => button.addEventListener('click', () => { $$('[data-blog-filter]').forEach(b => { b.classList.toggle('selected', b === button); b.setAttribute('aria-pressed', String(b===button)); }); const filtered = button.dataset.blogFilter === 'all' ? articles : articles.filter(a=>a.tag===button.dataset.blogFilter); $('#blog-grid').innerHTML = filtered.map(articleCard).join(''); refreshIcons(); })); }
async function shareArticle() { try { await navigator.clipboard.writeText(location.href); toast('Enlace copiado. Listo para compartir.'); } catch { toast('Copiá el enlace desde la barra de direcciones.'); } }

const shipments = [
  { code: 'NXR-DEMO-001', origin: 'Asunción', destination: 'Ciudad del Este', service: 'Transporte terrestre', status: 'En camino', cls: 'status-blue', step: 2, date: '18 oct · Ejemplo' },
  { code: 'NXR-DEMO-002', origin: 'Asunción', destination: 'Encarnación', service: 'Distribución', status: 'Entregado', cls: 'status-green', step: 3, date: '16 oct · Ejemplo' },
  { code: 'NXR-DEMO-003', origin: 'Coronel Oviedo', destination: 'Asunción', service: 'Documentos', status: 'Coordinando retiro', cls: 'status-amber', step: 0, date: '19 oct · Ejemplo' },
];
function renderPortal(tab) {
  $$('[data-portal-tab]').forEach(b=>b.classList.toggle('selected',b.dataset.portalTab===tab));
  const root = $('#portal-content');
  if (tab === 'envios') {
    root.innerHTML = `<div class="portal-heading"><div><span>BIENVENIDO A LA DEMO</span><h2>Tus envíos, conectados.</h2></div><a href="/contacto/" class="button button-red button-small">Nuevo envío ${icon('plus')}</a></div><div class="portal-stats"><div>${icon('package')}<span>Envíos de ejemplo</span><strong>03</strong></div><div>${icon('truck')}<span>En camino</span><strong>01</strong></div><div>${icon('package-check')}<span>Entregados</span><strong>01</strong></div></div><div class="shipment-search"><h3>Seguimiento de envíos</h3><label class="search-field">${icon('search')}<input id="shipment-search" type="search" placeholder="Buscá por código, origen o destino" aria-label="Buscar envío"></label></div><div class="table-scroll"><table class="shipment-table"><thead><tr><th>ENVÍO</th><th>RUTA</th><th>ESTADO</th><th>DETALLE</th></tr></thead><tbody id="shipment-rows"></tbody></table></div><p class="small-note portal-demo-note">${icon('info')} Los códigos NXR-DEMO corresponden a datos ficticios para explorar la experiencia.</p>`;
    updateShipments('');
    $('#shipment-search').addEventListener('input', e=>updateShipments(e.target.value));
  } else if (tab === 'documentos') {
    root.innerHTML = `<div class="portal-heading"><div><span>TODO EN UN SOLO LUGAR</span><h2>Documentos de ejemplo.</h2></div></div><p class="portal-description">Explorá cómo se organizarían los documentos de tu operación. Las descargas están identificadas como demostración.</p><div class="document-list">${shipments.map(s=>`<div>${icon('file-text')}<span><strong>Resumen · ${s.code}</strong><small>${s.origin} → ${s.destination} · Documento de muestra</small></span><button class="icon-button" data-download-shipment="${s.code}" aria-label="Descargar ejemplo ${s.code}">${icon('download')}</button></div>`).join('')}</div>`;
    $$('[data-download-shipment]').forEach(b=>b.addEventListener('click',()=>{const s=shipments.find(s=>s.code===b.dataset.downloadShipment);downloadFile(`${s.code}-ejemplo.txt`,`DEMOSTRACIÓN — NO ES UN DOCUMENTO OPERATIVO\n\nNexora Logistic\nCódigo: ${s.code}\nOrigen: ${s.origin}\nDestino: ${s.destination}\nEstado de ejemplo: ${s.status}\n\nTodos los datos son ficticios.`);}));
  } else {
    root.innerHTML = `<div class="portal-heading"><div><span>UNA MIRADA A TU OPERACIÓN</span><h2>Resumen de demostración.</h2></div></div><div class="portal-stats"><div>${icon('package')}<span>Envíos de ejemplo</span><strong>03</strong></div><div>${icon('map-pinned')}<span>Destinos de ejemplo</span><strong>03</strong></div><div>${icon('layers')}<span>Tipos de servicio</span><strong>03</strong></div></div><div class="report-list"><h3>Estado de los envíos de muestra</h3>${[['Coordinando retiro',1,'amber'],['En camino',1,'blue'],['Entregado',1,'green']].map(([t,n,c])=>`<div><span>${t}</span><div class="report-bar"><span class="${c}" style="width:33.33%"></span></div><strong>${n}</strong></div>`).join('')}<p class="small-note">Esta distribución refleja únicamente los tres envíos ficticios de la demo.</p></div><a href="/contacto/" class="button button-navy">Consultá por el acceso corporativo ${arrow()}</a>`;
  }
  refreshIcons();
}
function updateShipments(query) { const q=query.trim().toLowerCase(); const filtered=shipments.filter(s=>`${s.code} ${s.origin} ${s.destination}`.toLowerCase().includes(q)); $('#shipment-rows').innerHTML=filtered.length?filtered.map(s=>`<tr><td><strong>${s.code}</strong><small>${s.service}</small></td><td>${s.origin}<small>→ ${s.destination}</small></td><td><span class="status-badge ${s.cls}"><span></span>${s.status}</span></td><td><button class="icon-button" data-shipment="${s.code}" aria-label="Ver envío ${s.code}">${icon('arrow-up-right')}</button></td></tr>`).join(''):`<tr><td colspan="4" class="table-empty">No encontramos ese envío. Probá con NXR-DEMO-001.</td></tr>`; $$('[data-shipment]').forEach(b=>b.addEventListener('click',()=>shipmentModal(shipments.find(s=>s.code===b.dataset.shipment)))); refreshIcons(); }
function shipmentModal(shipment) { const modal=$('#modal'); modal.innerHTML=`<button class="modal-close icon-button" aria-label="Cerrar detalle">${icon('x')}</button><span class="demo-pill">ENVÍO FICTICIO · DEMOSTRACIÓN</span><h2 id="modal-title">${shipment.code}</h2><p>${shipment.origin} ${icon('arrow-right')} ${shipment.destination}</p><span class="status-badge ${shipment.cls}"><span></span>${shipment.status}</span><div class="tracking-timeline">${[['Solicitud coordinada','Datos de la operación recibidos.'],['Retiro de la carga','Preparación para iniciar el recorrido.'],['En camino','La carga continúa hacia su destino.'],['Entrega completada','Recepción confirmada en el destino.']].map(([t,d],i)=>`<div class="${i<=shipment.step?'done':''}"><span>${i<shipment.step?icon('check'):i+1}</span><div><strong>${t}</strong><p>${d}</p></div></div>`).join('')}</div><p class="small-note">Los estados son ilustrativos y no corresponden a una operación real.</p>`; refreshIcons(); modal.showModal(); $('.modal-close',modal).addEventListener('click',()=>modal.close()); modal.onclick=e=>{if(e.target===modal)modal.close();}; }
render(true);
